  const saveProd=async()=>{if(!pName)return;setSaving(true);const d={name:pName,productType:pType,category:pCat,unit:pUnit,price:Number(pPrice)||0,hsnCode:pHsn,taxPercent:Number(pTax)||18,description:pDesc};if(pEditId){await db.updateProduct(pEditId,d);await log("edit","product",pEditId,"Edited: "+pName);}else{await db.addProduct(d);await log("create","product",null,"Product: "+pName);}await loadAll();resetProd();setSaving(false);setModal(null);};

  // ===== INVENTORY ACTIONS =====
  const resetInvCat=()=>{setIcName("");setIcDesc("");setIcColor("#6366f1");setIcEditId(null);};
