  const invTotalValue=activeInvProds.reduce((s,p)=>s+(p.current_stock||0)*(p.buying_price||0),0);
  const invLowStock=activeInvProds.filter(p=>(p.current_stock||0)<=(p.min_stock||0)&&(p.min_stock||0)>0);
  const invTotalInvested=invTxns.filter(t=>t.type==="stock_in").reduce((s,t)=>s+(t.total_cost||0),0);
  const invCatChart=invCats.map(c=>{const ps=activeInvProds.filter(p=>p.category_id===c.id);const val=ps.reduce((s,p)=>s+(p.current_stock||0)*(p.buying_price||0),0);return{name:c.name,value:val,color:c.color};}).filter(c=>c.value>0);
  const exportInvCSV=()=>{let csv="SKU,Name,Category,Unit,Stock,Buy Price,Sell Price,Value\n";activeInvProds.forEach(p=>{csv+=`${p.sku},${p.name},${p.category_name||'-'},${p.unit},${p.current_stock},${p.buying_price},${p.selling_price},${(p.current_stock||0)*(p.buying_price||0)}\n`;});const b=new Blob([csv],{type:"text/csv"});const u=URL.createObjectURL(b);const a=document.createElement("a");a.href=u;a.download="Inventory_"+CM.replace(" ","_")+".csv";a.click();URL.revokeObjectURL(u);};

