      {/* Requisition Modal */}
      {modal==="req"&&<Md title="New Requisition" onClose={()=>{resetForm();setModal(null);}} wide>{renderPartyForm("Vendor")}<div className="my-4 border-t border-gray-100 pt-4">{renderDocForm()}</div><div className="my-4 border-t border-gray-100 pt-4"><h4 className="text-sm font-semibold text-gray-700 mb-2">Items</h4><ItemsEditor items={frmItems} setItems={setFrmItems} products={searchableProducts} showProductSearch={true}/></div><div className="my-3"><label className={LC}>Notes</label><input className={IC} value={frmNotes} onChange={e=>setFrmNotes(e.target.value)}/></div>{frmErr&&<p className="text-red-500 text-sm">{frmErr}</p>}<button onClick={createReq} disabled={saving} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 text-white font-semibold rounded-xl">Create Requisition</button></Md>}

      {/* PO Modal */}
      {modal==="po"&&<Md title="New Purchase Order" onClose={()=>{resetForm();setModal(null);}} wide>{renderPartyForm("Vendor")}<div className="my-4 border-t border-gray-100 pt-4">{renderDocForm({showDue:true,dueLabel:"Delivery Date"})}</div><div className="my-4 border-t border-gray-100 pt-4"><h4 className="text-sm font-semibold text-gray-700 mb-2">Items</h4><ItemsEditor items={frmItems} setItems={setFrmItems} products={searchableProducts} showProductSearch={true}/></div><div className="my-3"><label className={LC}>Notes</label><input className={IC} value={frmNotes} onChange={e=>setFrmNotes(e.target.value)}/></div>{frmErr&&<p className="text-red-500 text-sm">{frmErr}</p>}<button onClick={createPO} disabled={saving} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 text-white font-semibold rounded-xl">Create PO</button></Md>}

      {/* Edit PO Modal */}
      {modal==="editPO"&&<Md title="Edit Purchase Order" onClose={()=>{resetForm();setEditPOId(null);setEditPOItems([]);setModal(null);}} wide>{renderPartyForm("Vendor")}<div className="my-4 border-t border-gray-100 pt-4">{renderDocForm({showDue:true,dueLabel:"Delivery Date"})}</div><div className="my-4 border-t border-gray-100 pt-4"><h4 className="text-sm font-semibold text-gray-700 mb-2">Items</h4><ItemsEditor items={editPOItems} setItems={setEditPOItems} products={searchableProducts} showProductSearch={true}/></div><div className="my-3"><label className={LC}>Notes</label><input className={IC} value={frmNotes} onChange={e=>setFrmNotes(e.target.value)}/></div>{frmErr&&<p className="text-red-500 text-sm">{frmErr}</p>}<button onClick={saveEditPO} disabled={saving} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 text-white font-semibold rounded-xl">Save Changes</button></Md>}

      {/* B2B Invoice Modal */}
      {modal==="b2bInv"&&<Md title="New B2B Invoice" onClose={()=>{resetForm();setModal(null);}} wide>{renderPartyForm("Client")}<div className="my-4 border-t border-gray-100 pt-4">{renderDocForm({showDue:true,dueLabel:"Due Date",showPO:true})}</div><div className="my-4 border-t border-gray-100 pt-4"><h4 className="text-sm font-semibold text-gray-700 mb-2">Items</h4><ItemsEditor items={frmItems} setItems={setFrmItems} products={searchableProducts} showProductSearch={true}/></div><div className="my-3"><label className={LC}>Notes</label><input className={IC} value={frmNotes} onChange={e=>setFrmNotes(e.target.value)}/></div>{frmErr&&<p className="text-red-500 text-sm">{frmErr}</p>}<button onClick={createB2BInv} disabled={saving} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 text-white font-semibold rounded-xl">Create Invoice</button></Md>}

      {/* B2C Invoice Modal */}
      {modal==="b2cInv"&&<Md title="New B2C Invoice" onClose={()=>{resetForm();setModal(null);}} wide>{renderPartyForm("Customer")}<div className="my-4 border-t border-gray-100 pt-4">{renderDocForm({showDue:true,dueLabel:"Due Date"})}</div><div className="my-4 border-t border-gray-100 pt-4"><h4 className="text-sm font-semibold text-gray-700 mb-2">Items</h4><ItemsEditor items={frmItems} setItems={setFrmItems} products={searchableProducts} showProductSearch={true}/></div><div className="my-3"><label className={LC}>Notes</label><input className={IC} value={frmNotes} onChange={e=>setFrmNotes(e.target.value)}/></div>{frmErr&&<p className="text-red-500 text-sm">{frmErr}</p>}<button onClick={createB2CInv} disabled={saving} className="w-full py-3 bg-violet-600 hover:bg-violet-700 disabled:opacity-50 text-white font-semibold rounded-xl">Create B2C Invoice</button></Md>}

