      {modal==="editB2CInv"&&<Md title="Edit B2C Invoice" onClose={()=>{resetForm();setEditInvId(null);setEditInvItems([]);setModal(null);}} wide>{renderPartyForm("Customer")}<div className="my-4 border-t border-gray-100 pt-4">{renderDocForm({showDue:true,dueLabel:"Due Date"})}</div><div className="my-4 border-t border-gray-100 pt-4"><h4 className="text-sm font-semibold text-gray-700 mb-2">Items</h4><ItemsEditor items={editInvItems} setItems={setEditInvItems} products={searchableProducts} showProductSearch={true}/></div><div className="my-3"><label className={LC}>Notes</label><input className={IC} value={frmNotes} onChange={e=>setFrmNotes(e.target.value)}/></div>{frmErr&&<p className="text-red-500 text-sm">{frmErr}</p>}<button onClick={saveEditB2CInv} disabled={saving} className="w-full py-3 bg-violet-600 hover:bg-violet-700 disabled:opacity-50 text-white font-semibold rounded-xl">Save Changes</button></Md>}

      {/* Quote Modal */}
      {modal==="qt"&&<Md title="New Quotation" onClose={()=>{resetForm();setModal(null);}} wide>{renderPartyForm("Client")}<div className="my-4 border-t border-gray-100 pt-4">{renderDocForm({showDue:true,dueLabel:"Valid Until",showTerms:true})}</div><div className="my-4 border-t border-gray-100 pt-4"><h4 className="text-sm font-semibold text-gray-700 mb-2">Items</h4><ItemsEditor items={frmItems} setItems={setFrmItems} products={searchableProducts} showProductSearch={true}/></div><div className="my-3"><label className={LC}>Notes</label><input className={IC} value={frmNotes} onChange={e=>setFrmNotes(e.target.value)}/></div>{frmErr&&<p className="text-red-500 text-sm">{frmErr}</p>}<button onClick={createQt} disabled={saving} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 text-white font-semibold rounded-xl">Create Quote</button></Md>}

      {/* Edit Quote Modal */}
      {modal==="editQt"&&<Md title="Edit Quotation" onClose={()=>{resetForm();setEditQtId(null);setEditQtItems([]);setModal(null);}} wide>{renderPartyForm("Client")}<div className="my-4 border-t border-gray-100 pt-4">{renderDocForm({showDue:true,dueLabel:"Valid Until",showTerms:true})}</div><div className="my-4 border-t border-gray-100 pt-4"><h4 className="text-sm font-semibold text-gray-700 mb-2">Items</h4><ItemsEditor items={editQtItems} setItems={setEditQtItems} products={searchableProducts} showProductSearch={true}/></div><div className="my-3"><label className={LC}>Notes</label><input className={IC} value={frmNotes} onChange={e=>setFrmNotes(e.target.value)}/></div>{frmErr&&<p className="text-red-500 text-sm">{frmErr}</p>}<button onClick={saveEditQt} disabled={saving} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 text-white font-semibold rounded-xl">Save Changes</button></Md>}

      {/* Product Modal */}
      {modal==="prod"&&<Md title={pEditId?"Edit Product":"New Product"} onClose={()=>{resetProd();setModal(null);}}><div className="space-y-4"><div><label className={LC}>Name*</label><input className={IC} value={pName} onChange={e=>setPName(e.target.value)}/></div><div><label className={LC}>Type</label><div className="flex gap-2 mt-1"><select className={IC+" flex-1"} value={pType} onChange={e=>setPType(e.target.value)}><option value="Service">Service</option><option value="Product">Product</option>{prodTypes.map(t=>(<option key={t.id} value={t.name}>{t.name}</option>))}</select><input className={IC+" w-28"} placeholder="+ New type" value={newPType} onChange={e=>setNewPType(e.target.value)}/>{newPType&&<button onClick={async()=>{await db.addProductType(newPType);await loadAll();setPType(newPType);setNewPType("");}} className="px-3 py-2 bg-indigo-600 text-white text-xs rounded-lg whitespace-nowrap">Add</button>}</div></div><div><label className={LC}>Category</label><input className={IC} value={pCat} onChange={e=>setPCat(e.target.value)} placeholder="e.g. Electronics"/></div><div className="grid grid-cols-2 gap-3"><div><label className={LC}>Unit</label><select className={IC} value={pUnit} onChange={e=>setPUnit(e.target.value)}><option value="pcs">pcs</option><option value="kg">kg</option><option value="ltr">ltr</option><option value="hr">hr</option><option value="sqft">sqft</option></select></div><div><label className={LC}>Price</label><input type="number" className={IC} value={pPrice} onChange={e=>setPPrice(e.target.value)}/></div></div><div className="grid grid-cols-2 gap-3"><div><label className={LC}>HSN Code</label><input className={IC} value={pHsn} onChange={e=>setPHsn(e.target.value)}/></div><div><label className={LC}>Tax %</label><select className={IC} value={pTax} onChange={e=>setPTax(e.target.value)}>{GST_RATES.map(r=>(<option key={r} value={r}>{r}%</option>))}</select></div></div><div><label className={LC}>Description</label><input className={IC} value={pDesc} onChange={e=>setPDesc(e.target.value)}/></div><button onClick={saveProd} disabled={saving} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 text-white font-semibold rounded-xl">{pEditId?"Save":"Create"}</button></div></Md>}

      {/* Settle Modal */}
      {modal==="settle"&&settleTx&&<Md title="Settle Transaction (JV)" onClose={()=>{setSettleTx(null);setModal(null);}}><div className="space-y-4"><div className="bg-gray-50 rounded-xl p-4"><p className="text-sm text-gray-700"><span className="font-semibold">{settleTx.person}</span> — {fmt(settleTx.amount)}</p><p className="text-xs text-gray-400">{settleTx.note||settleTx.category}</p></div><div><label className={LC}>Settlement Note</label><input className={IC} value={settleNote} onChange={e=>setSettleNote(e.target.value)} placeholder="Reason for JV"/></div><p className="text-xs text-gray-400">This will reverse the transaction and adjust the balance.</p><button onClick={doSettle} disabled={saving} className="w-full py-3 bg-violet-600 hover:bg-violet-700 disabled:opacity-50 text-white font-semibold rounded-xl">Settle (Create JV)</button></div></Md>}

