      {modal==="payConfirm"&&payConfirmInv&&<Md title="Confirm Payment" onClose={()=>{setPayConfirmInv(null);setModal(null);}}><div className="space-y-4"><div className="bg-emerald-50 rounded-xl p-4"><p className="text-sm text-gray-700">Mark <span className="font-semibold">{payConfirmInv.number}</span> as paid?</p><p className="text-lg font-bold text-emerald-600 mt-1">{fmt(payConfirmInv.total)}</p><p className="text-xs text-gray-400">Client: {payConfirmInv.client.name}</p></div><p className="text-xs text-gray-400">This will record income and update the balance.</p><button onClick={executePayInvoice} disabled={saving} className="w-full py-3 bg-emerald-600 hover:bg-emerald-700 disabled:opacity-50 text-white font-semibold rounded-xl">Confirm Payment</button></div></Md>}

