      {modal==="logout"&&<Md title="Sign Out" onClose={()=>setModal(null)}><div className="space-y-4"><p className="text-gray-500 text-sm">Are you sure you want to sign out?</p><div className="flex gap-3"><button onClick={()=>setModal(null)} className="flex-1 py-2.5 bg-gray-100 text-gray-700 font-semibold rounded-xl">Cancel</button><button onClick={logout} className="flex-1 py-2.5 bg-red-500 text-white font-semibold rounded-xl">Sign Out</button></div></div></Md>}

